            const allowed = set[j].semver
            if (allowed.major === version.major &&
                allowed.minor === version.minor &&
                allowed.patch === version.patch) {
              return true
            }
          }
        }
        // Version has a -pre, but it's not one of the ones we like.
        continue
      }
      return true
    }
    return false
  }
}

module.exports = Range

