const satisfies = require('./functions/satisfies')
const maxSatisfying = require('./ranges/max-satisfying')
const minSatisfying = require('./ranges/min-satisfying')

console.log('Testing prereleaseTags option...\n')

// Test 1: rc tag should satisfy ^1.2.0
const test1 = satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] })
console.log('Test 1: satisfies("1.3.0-rc.1", "^1.2.0", { prereleaseTags: ["rc"] })')
console.log('  Expected: true')
console.log(`  Actual: ${test1}`)
console.log(`  ${test1 ? '✓ PASS' : '✗ FAIL'}\n`)

// Test 2: beta tag should NOT satisfy ^1.2.0 with prereleaseTags: ['rc']
const test2 = satisfies('1.3.0-beta.1', '^1.2.0', { prereleaseTags: ['rc'] })
console.log('Test 2: satisfies("1.3.0-beta.1", "^1.2.0", { prereleaseTags: ["rc"] })')
console.log('  Expected: false')
console.log(`  Actual: ${test2}`)
console.log(`  ${!test2 ? '✓ PASS' : '✗ FAIL'}\n`)

// Test 3: rc tag outside bounds should NOT satisfy
const test3 = satisfies('2.0.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] })
console.log('Test 3: satisfies("2.0.0-rc.1", "^1.2.0", { prereleaseTags: ["rc"] })')
console.log('  Expected: false')
console.log(`  Actual: ${test3}`)
console.log(`  ${!test3 ? '✓ PASS' : '✗ FAIL'}\n`)

// Test 4: Without prereleaseTags, rc should NOT satisfy ^1.2.0 (original behavior)
const test4 = satisfies('1.3.0-rc.1', '^1.2.0')
console.log('Test 4: satisfies("1.3.0-rc.1", "^1.2.0") without prereleaseTags')
console.log('  Expected: false')
console.log(`  Actual: ${test4}`)
console.log(`  ${!test4 ? '✓ PASS' : '✗ FAIL'}\n`)

// Test 5: maxSatisfying with prereleaseTags
const test5 = maxSatisfying(['1.2.0', '1.3.0-rc.1', '1.3.0-beta.1', '1.4.0'], '^1.2.0', { prereleaseTags: ['rc'] })
console.log('Test 5: maxSatisfying([...], "^1.2.0", { prereleaseTags: ["rc"] })')
console.log(`  Expected: 1.4.0`)
console.log(`  Actual: ${test5}`)
console.log(`  ${test5 === '1.4.0' ? '✓ PASS' : '✗ FAIL'}\n`)

