const test6 = minSatisfying(['1.2.0', '1.3.0-rc.1', '1.3.0-beta.1', '1.4.0'], '^1.2.0', { prereleaseTags: ['rc'] })
console.log('Test 6: minSatisfying([...], "^1.2.0", { prereleaseTags: ["rc"] })')
console.log(`  Expected: 1.2.0`)
console.log(`  Actual: ${test6}`)
console.log(`  ${test6 === '1.2.0' ? '✓ PASS' : '✗ FAIL'}\n`)

// Test 7: Test with Range.test()
const Range = require('./classes/range')
const SemVer = require('./classes/semver')
const range = new Range('^1.2.0', { prereleaseTags: ['rc'] })
const test7 = range.test('1.3.0-rc.1')
console.log('Test 7: new Range("^1.2.0", { prereleaseTags: ["rc"] }).test("1.3.0-rc.1")')
console.log('  Expected: true')
console.log(`  Actual: ${test7}`)
console.log(`  ${test7 ? '✓ PASS' : '✗ FAIL'}\n`)

