const semver = require('./index.js');

console.log('Comprehensive prereleaseTags tests\n');

const tests = [
  // Basic behavior - should match prerelease with matching tag
  {
    name: 'rc matches within range',
    fn: () => semver.satisfies('1.3.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }),
    expected: true,
  },
  // Different prerelease tag should not match
  {
    name: 'beta does not match when only rc is in tags',
    fn: () => semver.satisfies('1.3.0-beta.1', '^1.2.0', { prereleaseTags: ['rc'] }),
    expected: false,
  },
  // Outside bounds should not match
  {
    name: 'rc outside bounds does not match',
    fn: () => semver.satisfies('2.0.0-rc.1', '^1.2.0', { prereleaseTags: ['rc'] }),
    expected: false,
  },
  // Without prereleaseTags, should use default behavior
  {
    name: 'without prereleaseTags uses default behavior',
    fn: () => semver.satisfies('1.3.0-rc.1', '^1.2.0'),
    expected: false,
  },
  // With includePrerelease, should still match
  {
